void ThemeManager::reloadTheme() {
    loadTheme();
    Q_EMIT themeChanged();
}

void ThemeManager::loadTheme() {
    bool loaded = false;
    if (QFile::exists(m_jsonPath)) {
        loaded = loadJsonTheme(m_jsonPath);
    }
    if (!loaded && QFile::exists(m_gtkCssPath)) {
        loaded = loadGtkCssTheme(m_gtkCssPath);
    }

    computeGlassTints();
    updateVariantMap();
}

bool ThemeManager::loadJsonTheme(const QString &path) {
    QFile file(path);
    if (!file.open(QIODevice::ReadOnly)) return false;

    QJsonDocument doc = QJsonDocument::fromJson(file.readAll());
    if (!doc.isObject()) return false;

    QJsonObject obj = doc.object();
    if (obj.contains("surface")) m_windowBg = QColor(obj["surface"].toString());
    if (obj.contains("accent")) m_accent = QColor(obj["accent"].toString());
    if (obj.contains("text_primary")) m_textPrimary = QColor(obj["text_primary"].toString());
    if (obj.contains("text_secondary")) m_textSecondary = QColor(obj["text_secondary"].toString());
    if (obj.contains("error")) m_error = QColor(obj["error"].toString());
    return true;
}

bool ThemeManager::loadGtkCssTheme(const QString &path) {
    QFile file(path);
    if (!file.open(QIODevice::ReadOnly | QIODevice::Text)) return false;

    QString content = QString::fromUtf8(file.readAll());
    file.close();

    QRegularExpression re(R"(@define-color\s+([a-zA-Z0-9_-]+)\s+([^;]+);)");
    QRegularExpressionMatchIterator it = re.globalMatch(content);

    QColor cardBase = m_windowBg;

    while (it.hasNext()) {
        QRegularExpressionMatch match = it.next();
        QString name = match.captured(1).trimmed();
        QString val = match.captured(2).trimmed();

        if (name == "accent_color" || name == "accent_bg_color") {
            m_accent = QColor(val);
        } else if (name == "accent_fg_color") {
            m_accentFg = QColor(val);
        } else if (name == "window_bg_color") {
            m_windowBg = QColor(val);
        } else if (name == "window_fg_color") {
            m_textPrimary = QColor(val);
        } else if (name == "card_bg_color") {
            cardBase = QColor(val);
        } else if (name == "error_bg_color" || name == "destructive_bg_color") {
            m_error = QColor(val);
        } else if (name == "error_fg_color" || name == "destructive_fg_color") {
            m_errorFg = QColor(val);
        }
    }

    m_textSecondary = QColor(m_textPrimary.red(), m_textPrimary.green(), m_textPrimary.blue(), 180);
    return true;
}

void ThemeManager::computeGlassTints() {
    // Window glass: 65% alpha (allows Wayland compositor to blur wallpaper nicely)
    m_windowGlass = QColor(m_windowBg.red(), m_windowBg.green(), m_windowBg.blue(), 165);

    // Card glass: 85% alpha (ensures solid contrast so text is 100% legible)
    int r = std::clamp(m_windowBg.red() + 14, 0, 255);
    int g = std::clamp(m_windowBg.green() + 14, 0, 255);
    int b = std::clamp(m_windowBg.blue() + 20, 0, 255);
    m_cardGlass = QColor(r, g, b, 215);

    // 1px specular lighting rim
    m_cardHighlight = QColor(255, 255, 255, 38);

    // Button glass: elevated relative to card
    int br = std::clamp(r + 12, 0, 255);
    int bg = std::clamp(g + 12, 0, 255);
    int bb = std::clamp(b + 16, 0, 255);
    m_buttonGlass = QColor(br, bg, bb, 190);

    // Operator button glass: tinted slightly towards accent
    int or_ = std::clamp((br * 3 + m_accent.red()) / 4, 0, 255);
    int og = std::clamp((bg * 3 + m_accent.green()) / 4, 0, 255);
    int ob = std::clamp((bb * 3 + m_accent.blue()) / 4, 0, 255);
    m_buttonOperator = QColor(or_, og, ob, 210);

    m_buttonHover = QColor(255, 255, 255, 28);
    m_buttonPressed = QColor(0, 0, 0, 50);
}

void ThemeManager::updateVariantMap() {
    m_colors["windowBg"] = m_windowBg;
    m_colors["windowGlass"] = m_windowGlass;
    m_colors["cardGlass"] = m_cardGlass;
    m_colors["cardHighlight"] = m_cardHighlight;
    m_colors["buttonGlass"] = m_buttonGlass;
    m_colors["buttonOperator"] = m_buttonOperator;
    m_colors["buttonHover"] = m_buttonHover;
    m_colors["buttonPressed"] = m_buttonPressed;
    m_colors["accent"] = m_accent;
    m_colors["accentFg"] = m_accentFg;
    m_colors["textPrimary"] = m_textPrimary;
    m_colors["textSecondary"] = m_textSecondary;
    m_colors["error"] = m_error;
    m_colors["errorFg"] = m_errorFg;
}

